<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(12, 19, 39, 0.9);
      --panel-border: rgba(148, 163, 184, 0.2);
      --text: #e5eefc;
      --muted: #a9b8d4;
      --accent: #7dd3fc;
      --accent-strong: #38bdf8;
      --danger: #fda4af;
      --danger-strong: #fb7185;
      --success: #86efac;
      --shadow: 0 24px 80px rgba(2, 6, 23, 0.5);
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      margin: 0;
      min-height: 100%;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(56, 189, 248, 0.12), transparent 34%),
        linear-gradient(180deg, #11192e 0%, var(--bg) 62%);
      color: var(--text);
    }

    body {
      min-height: 100vh;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      transform: translateY(-180%);
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      background: #ffffff;
      color: #0f172a;
      font-weight: 700;
      text-decoration: none;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .page-shell {
      width: min(100%, 42rem);
      margin: 0 auto;
      padding: 4rem 1rem;
    }

    .card {
      padding: clamp(1.5rem, 4vw, 2.5rem);
      border: 1px solid var(--panel-border);
      border-radius: 1.5rem;
      background: var(--panel);
      backdrop-filter: blur(14px);
      box-shadow: var(--shadow);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      margin: 0 0 1rem;
      padding: 0.35rem 0.75rem;
      border: 1px solid rgba(125, 211, 252, 0.28);
      border-radius: 999px;
      background: rgba(14, 116, 144, 0.22);
      color: var(--accent);
      font-size: 0.88rem;
      letter-spacing: 0.01em;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 3rem);
      line-height: 1.05;
    }

    .intro {
      margin: 1rem 0 0;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    form {
      margin-top: 2rem;
    }

    .required-note {
      margin: 0 0 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .form-field {
      margin-bottom: 1.25rem;
    }

    label {
      display: inline-block;
      margin-bottom: 0.55rem;
      font-weight: 700;
    }

    .required-indicator {
      color: #f8fafc;
    }

    input {
      width: 100%;
      border: 1px solid rgba(148, 163, 184, 0.35);
      border-radius: 0.95rem;
      padding: 0.9rem 1rem;
      font: inherit;
      color: var(--text);
      background: rgba(15, 23, 42, 0.92);
      transition: border-color 150ms ease, box-shadow 150ms ease, background 150ms ease;
    }

    input::placeholder {
      color: #8ba1c7;
    }

    input:hover {
      border-color: rgba(125, 211, 252, 0.45);
    }

    input:focus-visible,
    button:focus-visible {
      outline: 3px solid transparent;
      box-shadow: 0 0 0 3px rgba(125, 211, 252, 0.75);
    }

    .field-help,
    .field-error,
    .status-message {
      margin: 0.5rem 0 0;
      font-size: 0.94rem;
      line-height: 1.45;
    }

    .field-help {
      color: var(--muted);
    }

    .field-error {
      color: var(--danger);
    }

    .is-invalid {
      border-color: var(--danger-strong);
      box-shadow: 0 0 0 1px rgba(251, 113, 133, 0.3);
    }

    .actions {
      display: flex;
      align-items: center;
      gap: 1rem;
      flex-wrap: wrap;
      margin-top: 1.5rem;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.35rem;
      font: inherit;
      font-weight: 700;
      color: #04111f;
      background: linear-gradient(135deg, #67e8f9, #38bdf8);
      cursor: pointer;
      transition: transform 150ms ease, filter 150ms ease;
    }

    button:hover {
      filter: brightness(1.06);
      transform: translateY(-1px);
    }

    .status-message {
      min-height: 1.45em;
      color: var(--success);
    }

    @media (max-width: 480px) {
      .page-shell {
        padding: 2rem 1rem;
      }

      .card {
        border-radius: 1.25rem;
      }

      .actions {
        align-items: stretch;
      }

      button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      .card,
      input,
      button,
      .skip-link {
        forced-color-adjust: auto;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>
  <script>
    const fieldState = {
      fullName: "",
      email: "",
      phone: ""
    };

    const errorState = {
      fullName: "",
      email: "",
      phone: ""
    };

    let statusMessage = "";

    const phoneFormatText = "Optional. Use digits and separators, for example: +1 (555) 123-4567.";

    function Field({
      id,
      name,
      label,
      type,
      required = false,
      autocomplete,
      helperText = ""
    }) {
      const helpId = helperText ? id + "-help" : "";
      const errorId = id + "-error";
      const describedBy = [helpId].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${id}">
            ${label}${required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
          </label>
          <input
            id="${id}"
            name="${name}"
            type="${type}"
            ${required ? "required" : ""}
            autocomplete="${autocomplete}"
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            aria-errormessage="${errorId}"
          >
          ${helperText ? `<p id="${helpId}" class="field-help">${helperText}</p>` : ""}
          <p id="${errorId}" class="field-error" hidden></p>
        </div>
      `;
    }

    function SupportForm() {
      return `
        <form id="support-form" novalidate>
          <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>
          ${Field({
            id: "full-name",
            name: "fullName",
            label: "Full name",
            type: "text",
            required: true,
            autocomplete: "name"
          })}
          ${Field({
            id: "email-address",
            name: "email",
            label: "Email address",
            type: "email",
            required: true,
            autocomplete: "email"
          })}
          ${Field({
            id: "phone-number",
            name: "phone",
            label: "Phone number (optional)",
            type: "tel",
            autocomplete: "tel",
            helperText: phoneFormatText
          })}
          <div class="actions">
            <button type="submit">Send request</button>
            <p class="status-message" id="form-status" role="status" aria-live="polite" aria-atomic="true"></p>
          </div>
        </form>
      `;
    }

    function App() {
      return `
        <a class="skip-link" href="#main-content">Skip to main content</a>
        <main id="main-content" class="page-shell" tabindex="-1">
          <section class="card" aria-labelledby="support-title">
            <p class="eyebrow">Support team</p>
            <h1 id="support-title">Contact support</h1>
            <p class="intro">
              Share your details and our team will follow up with the right next step.
            </p>
            ${SupportForm()}
          </section>
        </main>
      `;
    }

    function validateField(name, value) {
      const trimmedValue = value.trim();

      if (name === "fullName") {
        if (!trimmedValue) {
          return "Error: Enter your full name.";
        }
        if (trimmedValue.length < 2) {
          return "Error: Full name must be at least 2 characters.";
        }
      }

      if (name === "email") {
        if (!trimmedValue) {
          return "Error: Enter your email address.";
        }
        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailPattern.test(trimmedValue)) {
          return "Error: Enter a valid email address, such as name@example.com.";
        }
      }

      if (name === "phone" && trimmedValue) {
        const phonePattern = /^\+?[0-9\s().-]{7,20}$/;
        if (!phonePattern.test(trimmedValue)) {
          return "Error: Enter a valid phone number using digits and standard separators.";
        }
      }

      return "";
    }

    function render() {
      document.getElementById("app").innerHTML = App();

      const form = document.getElementById("support-form");
      const inputs = Array.from(form.querySelectorAll("input"));

      syncFormUI();

      inputs.forEach((input) => {
        input.addEventListener("input", handleInput);
        input.addEventListener("blur", handleBlur);
      });

      form.addEventListener("submit", handleSubmit);
    }

    function syncFormUI() {
      updateField("fullName", "full-name");
      updateField("email", "email-address");
      updateField("phone", "phone-number", "phone-number-help");
      document.getElementById("form-status").textContent = statusMessage;
    }

    function updateField(name, id, helpId) {
      const input = document.getElementById(id);
      const errorMessage = errorState[name];
      const errorId = id + "-error";
      const describedBy = [helpId, errorMessage ? errorId : ""].filter(Boolean).join(" ");

      input.value = fieldState[name];
      input.classList.toggle("is-invalid", Boolean(errorMessage));

      if (errorMessage) {
        input.setAttribute("aria-invalid", "true");
      } else {
        input.removeAttribute("aria-invalid");
      }

      if (describedBy) {
        input.setAttribute("aria-describedby", describedBy);
      } else {
        input.removeAttribute("aria-describedby");
      }

      const errorElement = document.getElementById(errorId);
      errorElement.textContent = errorMessage;
      errorElement.hidden = !errorMessage;
    }

    function handleInput(event) {
      const { name, value } = event.target;
      fieldState[name] = value;
      errorState[name] = validateField(name, value);
      if (statusMessage) {
        statusMessage = "";
      }
      syncFormUI();
    }

    function handleBlur(event) {
      const { name, value } = event.target;
      fieldState[name] = value;
      errorState[name] = validateField(name, value);
      syncFormUI();
    }

    function handleSubmit(event) {
      event.preventDefault();
      const form = event.currentTarget;
      const inputs = Array.from(form.querySelectorAll("input"));

      inputs.forEach((input) => {
        fieldState[input.name] = input.value;
        errorState[input.name] = validateField(input.name, input.value);
      });

      const firstInvalidName = inputs.find((input) => errorState[input.name])?.name;

      if (firstInvalidName) {
        statusMessage = "";
        syncFormUI();
        restoreFocus(firstInvalidName);
        return;
      }

      statusMessage = "Your support request is ready to send.";
      syncFormUI();
    }

    function restoreFocus(name) {
      const idByName = {
        fullName: "full-name",
        email: "email-address",
        phone: "phone-number"
      };

      const input = document.getElementById(idByName[name]);
      if (input) {
        input.focus();
      }
    }

    render();
  </script>
</body>
</html>
